');INSERT INTO DRIVERS (FullName, Phone, LicenseNumber) VALUES ('Sami Haddad',    '0781000003', 'LIC-1003');-- ---------------- ROUTES ------------------ R1: bus + driver | R2: bus only | R3: nothing assigned | R4: inactiveINSERT INTO ROUTES (RouteNumber, Name, StartPoint, Destination, ServiceArea, Capacity, IsActive, BusId, DriverId)VALUES ('R1', 'Abdoun Line', 'Abdoun', 'School', 'West Amman', 30, 1,        (SELECT BusId FROM BUSES WHERE PlateNumber = '11-12345'),        (SELECT DriverId FROM DRIVERS WHERE LicenseNumber = 'LIC-1001'));INSERT INTO ROUTES (RouteNumber, Name, StartPoint, Destination, ServiceArea, Capacity, IsActive, BusId, DriverId)VALUES ('R2', 'Jubeiha Line', 'Jubeiha', 'School', 'North Amman', 25, 1,        (SELECT BusId FROM BUSES WHERE PlateNumber = '22-67890'), NULL);INSERT INTO ROUTES (RouteNumber, Name, StartPoint, Destination, ServiceArea, Capacity, IsActive, BusId, DriverId)VALUES ('R3', 'Marka Line', 'Marka', 'School', 'East Amman', 20, 1, NULL, NULL);INSERT INTO ROUTES (RouteNumber, Name, StartPoint, Destination, ServiceArea, Capacity, IsActive, BusId, DriverId)VALUES ('R4', 'Sweileh Line', 'Sweileh', 'School', 'North Amman', 20, 0, NULL, NULL);-- ---------------- STOPS (some with no times) ----------------INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R1'), 'Abdoun Circle', 1, '06:45', '14:30');INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R1'), 'Sweifieh', 2, '07:00', '14:45');INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R1'), 'Dabouq', 3, '07:15', '15:00');INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R2'), 'Jubeiha Main St', 1, '06:50', '14:35');INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R2'), 'University Street', 2, NULL, NULL);INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R3'), 'Marka Square', 1, NULL, NULL);INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R3'), 'Airport Road', 2, NULL, NULL);INSERT INTO STOPS (RouteId, Name, StopOrder, PickupTime, DropoffTime)VALUES ((SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R4'), 'Sweileh Center', 1, '07:00', '14:40');-- ---------------- STUDENTS (parent 1 has two students) ----------------INSERT INTO STUDENTS (ParentId, FullName, Grade, ClassName, DateOfBirth)VALUES ((SELECT p.ParentId FROM PARENTS p JOIN USERS u ON u.UserId = p.UserId WHERE u.Email = 'ahmad@mail.com'),        'Yazan Ahmad', 'Grade 5', 'A', DATE '2015-04-12');INSERT INTO STUDENTS (ParentId, FullName, Grade, ClassName, DateOfBirth)VALUES ((SELECT p.ParentId FROM PARENTS p JOIN USERS u ON u.UserId = p.UserId WHERE u.Email = 'ahmad@mail.com'),        'Rama Ahmad', 'Grade 3', 'B', DATE '2017-09-03');INSERT INTO STUDENTS (ParentId, FullName, Grade, ClassName, DateOfBirth)VALUES ((SELECT p.ParentId FROM PARENTS p JOIN USERS u ON u.UserId = p.UserId WHERE u.Email = 'mona@mail.com'),        'Layan Saleh', 'Grade 6', 'A', DATE '2014-01-20');INSERT INTO STUDENTS (ParentId, FullName, Grade, ClassName, DateOfBirth)VALUES ((SELECT p.ParentId FROM PARENTS p JOIN USERS u ON u.UserId = p.UserId WHERE u.Email = 'mona@mail.com'),        'Tariq Saleh', 'Grade 2', 'C', DATE '2018-06-15');INSERT INTO STUDENTS (ParentId, FullName, Grade, ClassName, DateOfBirth)VALUES ((SELECT p.ParentId FROM PARENTS p JOIN USERS u ON u.UserId = p.UserId WHERE u.Email = 'khalil@mail.com'),        'Hadi Nasser', 'Grade 4', 'B', DATE '2016-11-30');-- ---------------- SUBSCRIPTIONS (all four statuses) ----------------INSE