TransportType, Fee, Status, StartDate, EndDate)VALUES ('SUB-2026-0005',        (SELECT StudentId FROM STUDENTS WHERE FullName = 'Hadi Nasser'),        (SELECT RouteId FROM ROUTES WHERE RouteNumber = 'R3'),        (SELECT s.StopId FROM STOPS s JOIN ROUTES r ON r.RouteId = s.RouteId WHERE r.RouteNumber = 'R3' AND s.StopOrder = 1),        'RoundTrip', 250, 'Cancelled', DATE '2026-09-01', DATE '2027-01-31');-- ---------------- PAYMENTS (Paid / Partial / Unpaid) ------------------ Recorded manually by the admin (no real online payment)INSERT INTO PAYMENTS (SubscriptionId, AmountDue, AmountPaid, Status, PaymentDate, RecordedBy, Notes)VALUES ((SELECT SubscriptionId FROM SUBSCRIPTIONS WHERE ReferenceNumber = 'SUB-2026-0001'),        300, 300, 'Paid', DATE '2026-08-25',        (SELECT UserId FROM USERS WHERE Email = 'admin@school.edu'), 'Paid in cash at the office');INSERT INTO PAYMENTS (SubscriptionId, AmountDue, AmountPaid, Status, PaymentDate, RecordedBy, Notes)VALUES ((SELECT SubscriptionId FROM SUBSCRIPTIONS WHERE ReferenceNumber = 'SUB-2026-0003'),        280, 100, 'Partial', DATE '2026-08-28',        (SELECT UserId FROM USERS WHERE Email = 'admin@school.edu'), 'First installment');INSERT INTO PAYMENTS (SubscriptionId, AmountDue, AmountPaid, Status, PaymentDate, RecordedBy, Notes)VALUES ((SELECT SubscriptionId FROM SUBSCRIPTIONS WHERE ReferenceNumber = 'SUB-2026-0002'),        180, 0, 'Unpaid', NULL, NULL, NULL);-- ---------------- CHANGE_REQUESTS ----------------INSERT INTO CHANGE_REQUESTS (SubscriptionId, RequestType, Reason, Status)VALUES ((SELECT SubscriptionId FROM SUBSCRIPTIONS WHERE ReferenceNumber = 'SUB-2026-0001'),        'Modify', 'Want to change pickup stop', 'Pending');INSERT INTO CHANGE_REQUESTS (SubscriptionId, RequestType, Reason, Status)VALUES ((SELECT SubscriptionId FROM SUBSCRIPTIONS WHERE ReferenceNumber = 'SUB-2026-0003'),        'Cancel', 'Moving to another area', 'Rejected');COMMIT;